from typing import Any, Union, TypeVar, cast
from enum import Enum


T = TypeVar("T")
EnumT = TypeVar("EnumT", bound=Enum)


def from_str(x: Any) -> str:
    assert isinstance(x, str)
    return x


def from_int(x: Any) -> int:
    assert isinstance(x, int) and not isinstance(x, bool)
    return x


def from_union(fs, x):
    for f in fs:
        try:
            return f(x)
        except:
            pass
    assert False


def to_class(c, x: Any) -> dict:
    assert isinstance(x, c)
    return cast(Any, x).to_dict()


def to_enum(c, x: Any) -> EnumT:
    assert isinstance(x, c)
    return x.value


class Child:
    name: str

    def __init__(self, name: str) -> None:
        self.name = name

    @staticmethod
    def from_dict(obj: Any) -> 'Child':
        assert isinstance(obj, dict)
        name = from_str(obj["name"])
        return Child(name)

    def to_dict(self) -> dict:
        result: dict = {}
        result["name"] = from_str(self.name)
        return result


class Status(Enum):
    READY = "ready"
    DONE = "done"


class TopLevel:
    child: Child
    status: Status
    value: Union[int, str]

    def __init__(self, child: Child, status: Status, value: Union[int, str]) -> None:
        self.child = child
        self.status = status
        self.value = value

    @staticmethod
    def from_dict(obj: Any) -> 'TopLevel':
        assert isinstance(obj, dict)
        child = Child.from_dict(obj["child"])
        status = Status(obj["status"])
        value = from_union([from_int, from_str], obj["value"])
        return TopLevel(child, status, value)

    def to_dict(self) -> dict:
        result: dict = {}
        result["child"] = to_class(Child, self.child)
        result["status"] = to_enum(Status, self.status)
        result["value"] = from_union([from_int, from_str], self.value)
        return result


def top_level_from_dict(s: Any) -> TopLevel:
    return TopLevel.from_dict(s)


def top_level_to_dict(x: TopLevel) -> Any:
    return to_class(TopLevel, x)

